(function(root){const table="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/",models={};function decode(s){const bytes=[];let value=0,bits=0;for(let i=0;i<s.length;i++){const c=table.indexOf(s[i]);if(c<0)break;value=(value<<6)|c;bits+=6;if(bits>=8){bits-=8;bytes.push((value>>bits)&255);}}return bytes;}for(const[name,[scale,s,index]]of Object.entries({"sculptHead":[0.45066758293153225,"",""],"sculptTorso":[0.5458569755002263,"",""],"sculptArm":[0.3089133901266986,"",""],"sculptLeg":[0.3919446751980251,"",""],"sculptGlove":[0.15706144266814528,"",""],"sculptBoot":[0.26214004500038907,"",""]})){const bytes=decode(s),indices=decode(index),vertices=new Float32Array(bytes.length/2);for(let i=0;i<vertices.length;i++){let q=bytes[i*2]|bytes[i*2+1]<<8;if(q>32767)q-=65536;vertices[i]=q/32767*(i%6<3?scale:1);}const out=new Float32Array(indices.length*3);for(let i=0;i<indices.length/2;i++){const at=(indices[i*2]|indices[i*2+1]<<8)*6;for(let j=0;j<6;j++)out[i*6+j]=vertices[at+j];}models[name]=Array.from(out);}root.MoonSculptedModels=Object.assign(root.MoonSculptedModels||{},models);root.MoonSculptedCatReady=true;try{const r=root.MoonGame&&root.MoonGame.renderer;if(r&&r.meshes&&r.meshes.round)for(const k of Object.keys(models))if(!r.meshes[k])r.addMesh(k,models[k]);}catch(e){}})(globalThis);
